#!/bin/sh
r=/run/opdbus-release/ready
IFS= read -r state < "$r" || exit 111
case "$state" in
  complete\ *) ;;
  transition\ *)
    if grep -Fqx 'q op-grpc-bridge' "$r" && ! grep -Fqx 'allow op-grpc-bridge' "$r"; then exit 111; fi ;;
  *) exit 111 ;;
esac
exec /usr/local/libexec/op-dbus/sv/op-grpc-bridge/run "$@"
